inline const Tenant* Note::owner() const {
    if (owner_) {
        return owner_.get();
    }
    if (!is_loaded("owner")) {
        return nullptr;
    }
    auto* view = root.resolve_relation_option<Tenant>(ENTITY_NAME, id(), "owner");
    if (view) {
        return *view ? &**view : nullptr;
    }
    return root.resolve_entity<Tenant>(ownerId());
}

inline const Tenant* Note::linked() const {
    if (linked_) {
        return linked_.get();
    }
    if (!is_loaded("linked")) {
        return nullptr;
    }
    auto* view = root.resolve_relation_option<Tenant>(ENTITY_NAME, id(), "linked");
    if (view) {
        return *view ? &**view : nullptr;
    }
    return root.resolve_entity<Tenant>(linkedId());
}

inline const Tenant* Note::optionalLinked() const {
    if (optional_linked_) {
        return optional_linked_.get();
    }
    if (!is_loaded("optional_linked")) {
        return nullptr;
    }
    auto* view = root.resolve_relation_option<Tenant>(ENTITY_NAME, id(), "optional_linked");
    if (view) {
        return *view ? &**view : nullptr;
    }
    auto foreign = optionalLinkedId();
    return foreign ? root.resolve_entity<Tenant>(*foreign) : nullptr;
}

