inline MutationValues Note::into_values() && {
    auto r = memory_resource();
    MutationValues values(r);
    values.fields.emplace(String("id", r), generated_detail::encode(r, id_));
    values.fields.emplace(String("code", r), generated_detail::encode(r, code_));
    values.fields.emplace(String("count", r), generated_detail::encode(r, count_));
    values.fields.emplace(String("payload", r), generated_detail::encode(r, payload_));
    values.fields.emplace(String("version", r), generated_detail::encode(r, version_));
    values.fields.emplace(String("owner_id", r), generated_detail::encode(r, owner_id_));
    values.fields.emplace(String("linked_id", r), generated_detail::encode(r, linked_id_));
    values.fields.emplace(String("optional_linked_id", r),
                          generated_detail::encode(r, optional_linked_id_));
    detail::EntityRuntimeAccess::retain_loaded_native_values(values, load_state);
    if (owner_) {
        values.fields.emplace(String("owner", r),
                              Value(r, std::move(*owner_).into_values().fields));
    }
    if (linked_) {
        values.fields.emplace(String("linked", r),
                              Value(r, std::move(*linked_).into_values().fields));
    }
    if (optional_linked_) {
        values.fields.emplace(String("optional_linked", r),
                              Value(r, std::move(*optional_linked_).into_values().fields));
    }
    inject_runtime(values);
    return values;
}

inline Note& Note::updateOwner(const Tenant& value) {
    owner_ = detail::make_box<Tenant>(memory_resource(), value);
    updateOwnerId(value.id());
    return *this;
}

inline Note& Note::updateLinked(const Tenant& value) {
    linked_ = detail::make_box<Tenant>(memory_resource(), value);
    updateLinkedId(value.id());
    return *this;
}

inline Note& Note::updateOptionalLinked(const Tenant& value) {
    optional_linked_ = detail::make_box<Tenant>(memory_resource(), value);
    updateOptionalLinkedId(value.id());
    return *this;
}
